function validate([nums]) {
  if (!Array.isArray(nums) || nums.length < 1 || nums.length > 50000) return 'nums needs 1 to 5 * 10^4 values.';
  if (nums.some(v => !Number.isInteger(v) || v < 1 || v > 1048575)) return 'Each value is an integer from 1 to 2^20 - 1.';
  return null;
}

