function maximumStrongPairXor(nums) {
  const BITS = 20;
  nums.sort((a, b) => a - b);
  const children = [[0, 0]];
  const count = [0];

  function update(value, delta) {
    let node = 0;
    for (let bit = BITS - 1; bit >= 0; bit--) {
      const b = (value >> bit) & 1;
      if (children[node][b] === 0) {
        children[node][b] = children.length;
        children.push([0, 0]);
        count.push(0);
      }
      node = children[node][b];
      count[node] += delta;
    }
  }

  function bestXor(value) {
    let node = 0;
    let result = 0;
    for (let bit = BITS - 1; bit >= 0; bit--) {
      const b = (value >> bit) & 1;
      const opposite = children[node][1 - b];
      if (opposite !== 0 && count[opposite] > 0) {
        result |= 1 << bit;
        node = opposite;
      } else {
        node = children[node][b];
      }
    }
    return result;
  }

  let best = 0;
  let left = 0;
  for (let right = 0; right < nums.length; right++) {
    update(nums[right], 1);
    while (2 * nums[left] < nums[right]) {
      update(nums[left], -1);
      left++;
    }
    best = Math.max(best, bestXor(nums[right]));
  }
  return best;
}

