function generate(rand, size) {
  const MAX = (1 << 20) - 1;
  const logUniform = () => Math.min(MAX, Math.max(1, Math.floor(2 ** (rand() * 20))));
  if (size === 'large') {
    const uniform = rand() < 0.5;
    return [Array.from({ length: 2000 }, () => (uniform ? 1 + Math.floor(rand() * MAX) : logUniform()))];
  }
  const n = 1 + Math.floor(rand() * 8);
  const ranges = [8, 64, 1000];
  const range = ranges[Math.floor(rand() * ranges.length)];
  const nums = Array.from({ length: n }, () => 1 + Math.floor(rand() * range));
  if (rand() < 0.2) nums[Math.floor(rand() * n)] = logUniform();
  return [nums];
}
